import java.util.Scanner;

public class FloralClock {

    private static final int MOD = 998244353;
    private static final int MAXN = 50000;

    private static int[] fact = new int[2 * MAXN + 5];
    private static int[] invFact = new int[2 * MAXN + 5];
    private static int[] inv = new int[2 * MAXN + 5];
    private static int[] pow2 = new int[MAXN + 5];
    private static int[] dp = new int[MAXN + 5];
    private static int[] sum = new int[MAXN + 5];

    private static int modPow(int a, int e) {
        long res = 1;
        long cur = a;
        while (e > 0) {
            if ((e & 1) == 1) res = res * cur % MOD;
            cur = cur * cur % MOD;
            e >>= 1;
        }
        return (int) res;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();

        fact[0] = 1;
        for (int i = 1; i <= 2 * n; i++) {
            fact[i] = (int) ((long) fact[i - 1] * i % MOD);
        }
        invFact[2 * n] = modPow(fact[2 * n], MOD - 2);
        for (int i = 2 * n; i >= 1; i--) {
            invFact[i - 1] = (int) ((long) invFact[i] * i % MOD);
        }
        for (int i = 1; i <= 2 * n; i++) {
            inv[i] = (int) ((long) fact[i - 1] * invFact[i] % MOD);
        }
        pow2[0] = 1;
        for (int i = 1; i <= n; i++) {
            pow2[i] = (pow2[i - 1] << 1) % MOD;
        }

        dp[0] = 1;
        sum[0] = 1;
        for (int i = 1; i <= n; i++) {
            if (i % 2 == 1) {
                dp[i] = 0;
            } else {
                int k = i / 2;
                dp[i] = (int) ((long) fact[i] * invFact[k] % MOD * invFact[k] % MOD * inv[i] % MOD);
            }
            sum[i] = (sum[i - 1] + dp[i]) % MOD;
        }

        long ans = 0;
        for (int k = 0; k <= n; k++) {
            int m = n - k;
            if (m < 0) break;
            if (m % 2 == 1) continue;

            int waysMatch = dp[m];
            int waysAssign = (int) ((long) fact[n] * invFact[k] % MOD * invFact[m] % MOD);
            long term = (long) waysMatch * waysAssign % MOD * pow2[k] % MOD;
            ans = (ans + term) % MOD;
        }

        System.out.println(ans);
    }
}
